-- B39 of specs/004-sessions/tasks.md (the note under T036; the owner's decision (c) of 2026-11-11 on
-- PR #133's review, round 1, Major 1; data-model.md §2.7 and §6; ERD v1.15, changelog row 34).
-- Generated by `prisma migrate diff --from-config-datasource --to-schema prisma/schema --script`
-- against a database holding every migration before it, then extended by hand with rule 49.
--
-- What it lands: `disputes.covered_by_case_id`, on a closed `student_suspended` case the case that
-- owes the sessions its suspension cancelled, with its plain index (§14) and its foreign key to
-- `disputes`. `cases.get`'s `covers` reads it instead of comparing `resolved_at` (the database's
-- clock) with `created_at` (the application's). Additive: every existing row is NULL, which rule 49
-- admits, so nothing is counted before it runs on `ijazah`.

-- AlterTable
ALTER TABLE "disputes" ADD COLUMN     "covered_by_case_id" UUID;

-- CreateIndex
CREATE INDEX "disputes_covered_by_case_id_idx" ON "disputes"("covered_by_case_id");

-- AddForeignKey
ALTER TABLE "disputes" ADD CONSTRAINT "disputes_covered_by_case_id_fkey" FOREIGN KEY ("covered_by_case_id") REFERENCES "disputes"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- Rule 49: the link only on a closed suspension case, never to itself.
ALTER TABLE "disputes" ADD CONSTRAINT "disputes_covered_by_check"
    CHECK ("covered_by_case_id" IS NULL
        OR ("kind" = 'compensation_case' AND "reason" = 'student_suspended'
            AND "status" <> 'open' AND "covered_by_case_id" <> "id"));
